/* Режим сейчас: настройки difficulty и turnBased — режим идущей игры (game.js, applyDiff). */
var dkTB = {};
LAB.dk = function () {
  var S = LAB.settings || {}, k = LAB.DIFF[S.difficulty] ? S.difficulty : 1, d = LAB.DIFF[k];
  if (!S.turnBased) return d;
  if (!dkTB[k]) {
    var e = LAB.TB_ECON, o = {};
    for (var p in d) o[p] = d[p];
    o.price = (d.price || 1) * e.price; o.sell = (d.sell || 1) * e.sell; o.cash = (d.cash || 1) * e.cash; o.loot = (d.loot || 1) * e.loot;
    o.med = (d.med || 1) * e.med; o.bat = (d.bat || 4) + e.bat; o.capBat = Math.max(1, (d.capBat || 5) + e.capBat);
    o.lose = Math.min(0.6, (d.lose || 0) + (d.lose ? e.lose : 0)); o.tb = true;
    dkTB[k] = o;
  }
  return dkTB[k];
};
