var armorSeq = 0;
LAB.makeArmor = function (base, lvl, qual, idHint) {
  var b = LAB.ARMORS[base];
  qual = qual == null ? 1 : qual;
  var a = { id: idHint || ("a" + (++armorSeq) + "_" + Math.floor(Math.random() * 1e6).toString(36) + "_" + base), base: base, lvl: lvl, qual: qual, up: 0,
    def: Math.max(1, Math.round(b.def * (1 + 0.12 * (lvl - 1)) * LAB.QUAL_MULT[qual])) };
  a.name = LAB.QUAL[b.g][qual] + " " + b.n;
  return a;
};
/* (2.0) Мастерская — на первом этаже уровня и на каждом третьем: больше
   двух этажей подряд без верстака не бывает, и на стыке уровней тоже. */
LAB.shopFloor = function (F) { return F === 1 || F % 3 === 0; };
/* (2.0) Износ брони: с половины состояния защита слабеет, на нуле — шесть
   десятых прежней. Состояние — a.cond (нет поля — 100). */
LAB.armorCond = function (a) { return a && a.cond != null ? a.cond : 100; };
LAB.armorCondK = function (a) { var c = LAB.armorCond(a); return c >= 50 ? 1 : 0.6 + 0.8 * c / 100; };
/* Защита брони с учётом вставленных пластин и износа. */
LAB.armorDef = function (a) { return a ? Math.round(a.def * (1 + 0.1 * (a.up || 0)) * LAB.armorCondK(a)) : 0; };
LAB.genArmor = function (r, L, F, opts) {
  opts = opts || {};
  var pool = [], k;
  for (k in LAB.ARMORS) if (LAB.ARMORS[k].depth <= L && (opts.min == null || LAB.ARMORS[k].depth >= opts.min)) pool.push(k);
  /* (проверка перед сборкой) брони такой глубины нет — любая доступная: прежде пустой выбор ронял
     окно торгового терминала почти на половине уровней */
  if (!pool.length && opts.min != null && !opts.base) return LAB.genArmor(r, L, F, { bonus: opts.bonus, id: opts.id });
  /* чаще попадается броня своей глубины */
  var near = pool.filter(function (x) { return LAB.ARMORS[x].depth >= L - (L > 10 ? 12 : 2); });
  var base = opts.base || (near.length && r.chance(0.65) ? r.pick(near) : r.pick(pool));
  var q = r.next() + Math.min(0.4, L * 0.02) + (opts.bonus || 0) * 0.5;
  var qual = q < 0.2 ? 0 : q < 0.55 ? 1 : q < 0.8 ? 2 : q < 0.93 ? 3 : q < 0.99 ? 4 : 5;
  return LAB.makeArmor(base, LAB.foeLevel(L, F), Math.min(5, qual), opts.id);
};

